# WAR — resilient tick (each phase isolated; returns 200 + per-phase errors, never 500)
# Run from project root:  powershell -ExecutionPolicy Bypass -File .\install-resilient-tick.ps1
$ErrorActionPreference = 'Stop'
if (-not (Test-Path 'src\api')) { Write-Host 'ERROR: run from project root' -ForegroundColor Red; exit 1 }
$b64 = @'

'@
[IO.File]::WriteAllBytes((Join-Path (Get-Location) 'src\api\wiredApp.ts'), [Convert]::FromBase64String($b64))
Write-Host '  wrote src/api/wiredApp.ts' -ForegroundColor Green
Write-Host 'Then: npm run build; git add -A; git commit -m "resilient tick"; git push' -ForegroundColor Cyan